BEGIN;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM global_prod.bancos_regla_asignacion_usuario WHERE activo IS FALSE OR version<>1 OR reemplaza_regla_id IS NOT NULL OR origen='MANUAL') OR EXISTS(SELECT 1 FROM global_temp.bancos_regla_asignacion_usuario WHERE activo IS FALSE OR version<>1 OR reemplaza_regla_id IS NOT NULL OR origen='MANUAL') THEN RAISE EXCEPTION 'No se puede retirar el versionado: ya existen reglas administradas'; END IF; END $$;
DROP INDEX IF EXISTS global_prod.bancos_regla_asignacion_usuario_reemplaza_uk; DROP INDEX IF EXISTS global_prod.bancos_regla_asignacion_usuario_activa_uk; DROP INDEX IF EXISTS global_temp.bancos_regla_asignacion_usuario_reemplaza_uk; DROP INDEX IF EXISTS global_temp.bancos_regla_asignacion_usuario_activa_uk;
ALTER TABLE global_prod.bancos_regla_asignacion_usuario DROP CONSTRAINT IF EXISTS bancos_regla_asignacion_usuario_reemplaza_fk,DROP CONSTRAINT IF EXISTS bancos_regla_asignacion_usuario_origen_check,DROP CONSTRAINT IF EXISTS bancos_regla_asignacion_usuario_version_check,DROP COLUMN IF EXISTS origen,DROP COLUMN IF EXISTS reemplaza_regla_id,DROP COLUMN IF EXISTS version;
ALTER TABLE global_temp.bancos_regla_asignacion_usuario DROP CONSTRAINT IF EXISTS bancos_regla_asignacion_usuario_reemplaza_fk,DROP CONSTRAINT IF EXISTS bancos_regla_asignacion_usuario_origen_check,DROP CONSTRAINT IF EXISTS bancos_regla_asignacion_usuario_version_check,DROP COLUMN IF EXISTS origen,DROP COLUMN IF EXISTS reemplaza_regla_id,DROP COLUMN IF EXISTS version;
ALTER TABLE global_prod.bancos_regla_asignacion_usuario ADD CONSTRAINT bancos_regla_asignacion_usuario_uk UNIQUE(configuracion_id,subtipo_valor_zetti_id,usuario);
ALTER TABLE global_temp.bancos_regla_asignacion_usuario ADD CONSTRAINT bancos_regla_asignacion_usuar_configuracion_id_subtipo_valo_key UNIQUE(configuracion_id,subtipo_valor_zetti_id,usuario);
COMMIT;
